pub(crate) fn node_text<'a>(node: tree_sitter::Node<'a>, source: &'a str) -> &'a str {
    &source[node.start_byte()..node.end_byte()]
}
pub(crate) fn extract_func_name<'a>(node: tree_sitter::Node<'a>, source: &'a str) -> Option<&'a str> {
    if node.kind() != "function_call" {
        return None;
    }
    let name_node = node.child_by_field_name("name")?;
    Some(&source[name_node.start_byte()..name_node.end_byte()])
}
pub(crate) fn extract_command_name<'a>(node: tree_sitter::Node<'a>, source: &'a str) -> Option<&'a str> {
    if node.kind() != "command" {
        return None;
    }
    let name_node = node.child(0)?;
    if name_node.kind() == "command_name" {
        Some(&source[name_node.start_byte()..name_node.end_byte()])
    } else {
        None
    }
}
pub(crate) fn extract_command_args<'a>(node: tree_sitter::Node<'a>, source: &'a str) -> Vec<&'a str> {
    let mut args = Vec::new();
    let count = node.child_count();
    for i in 0..count {
        if let Some(child) = node.child(i) {
            // Skip the command_name (first child) and punctuation.
            if child.kind() == "command_name" || child.kind() == ";" || child.kind() == "," {
                continue;
            }
            let text = node_text(child, source).trim();
            if !text.is_empty() {
                args.push(text);
            }
        }
